import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const primitiveResults = [];
  let disposed = false;

  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const gradientTop = vec3(0.043, 0.043, 0.063);
  const gradientMid = vec3(0.086, 0.086, 0.114);
  const gradientBottom = vec3(0.086, 0.086, 0.114);

  const backdropMaterial = new MeshBasicNodeMaterial();
  const gradientT = smoothstep(0.0, 1.0, uv().y);
  const firstGradient = mix(gradientBottom, gradientMid, smoothstep(0.0, 0.58, gradientT));
  backdropMaterial.colorNode = mix(firstGradient, gradientTop, smoothstep(0.58, 1.0, gradientT));
  resources.push(backdropMaterial);

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial
  );
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: '#16161d'
  });
  resources.push(surfaceMaterial);

  const surface = new Mesh(
    new PlaneGeometry(3.65, 2.35),
    surfaceMaterial
  );
  surface.position.set(0, 0, -0.08);
  root.add(surface);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  resources.push(shadowMaterial);

  const contactShadow = new Mesh(
    new CircleGeometry(1.85, 48),
    shadowMaterial
  );
  contactShadow.scale.set(1.35, 0.34, 1);
  contactShadow.position.set(0, -1.18, -0.02);
  root.add(contactShadow);

  const imageMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true
  });
  resources.push(imageMaterial);

  const imagePlane = new Mesh(
    new PlaneGeometry(3.35, 1.72),
    imageMaterial
  );
  imagePlane.position.set(0, 0.24, 0.02);
  root.add(imagePlane);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  resources.push(accentMaterial);

  const accentBar = new Mesh(
    new PlaneGeometry(0.52, 0.045),
    accentMaterial
  );
  accentBar.position.set(-1.35, -0.93, 0.08);
  root.add(accentBar);

  const labelMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2'
  });
  resources.push(labelMaterial);

  const labelRule = new Mesh(
    new PlaneGeometry(0.9, 0.012),
    labelMaterial
  );
  labelRule.position.set(0.86, -0.92, 0.08);
  root.add(labelRule);

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((texture) => {
        if (disposed) {
          texture.dispose?.();
          return;
        }
        imageMaterial.map = texture;
        imageMaterial.needsUpdate = true;
        resources.push(texture);
      })
      .catch(() => {});
  }

  let textOffset = -1.34;
  for (const item of items) {
    const text = String(item?.text ?? '');
    if (!text) continue;

    const textObject = ctx.fontAtlas.createText(text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: item.role === 'label' ? 2 : 0
    });

    textObject.position.set(textOffset, -0.72, 0.11);
    root.add(textObject);
    textOffset += 0.08;
  }

  const timeline = gsap.timeline();
  timeline.fromTo(
    surface.scale,
    { x: 0.985, y: 0.985, z: 1 },
    { x: 1.0, y: 1.0, z: 1, duration: 0.7, ease: 'power3.out' }
  );
  timeline.fromTo(
    imagePlane.position,
    { y: 0.04 },
    { y: 0.24, duration: 0.7, ease: 'power3.out' },
    '<'
  );

  for (const primitive of config.cinematicPrimitives ?? []) {
    const result = ctx.primitives[primitive.name](
      root,
      primitive.params
    );
    primitiveResults.push(result);
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    timeline.kill();

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    root.traverse((object) => {
      object.geometry?.dispose?.();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const entry of material) entry?.dispose?.();
      } else {
        material?.dispose?.();
      }
    });

    for (const resource of resources) {
      resource?.dispose?.();
    }
  };

  return root;
}
